import React, { useState, useEffect } from 'react';
import axios from 'axios';
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap-icons/font/bootstrap-icons.css';

function Ordersummary() {
  const [data, setData] = useState([]);
  const [search, setSearch] = useState('');
  const [rowsPerPage, setRowsPerPage] = useState(7);
  const [currentPage, setCurrentPage] = useState(1);
  const [sortConfig, setSortConfig] = useState({ key: null, direction: 'asc' });
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        setError(null);
        let allOrders = [];
        let page = 1;
        let hasMore = true;

        while (hasMore) {
          const response = await axios.get(
            `http://localhost:5000/api/orders/orderuser?page=${page}&size=${rowsPerPage}`
          );
          const { data: fetchedOrders, total } = response.data;
          allOrders = [...allOrders, ...fetchedOrders];

          if (fetchedOrders.length === 0 || allOrders.length >= total) {
            hasMore = false;
          }
          page++;
        }

        const transformedData = allOrders.flatMap(order => {
          const items = Array.isArray(order.orderedItems)
            ? order.orderedItems
            : typeof order.orderedItems === 'string'
              ? JSON.parse(order.orderedItems)
              : [];

          return items.map(product => ({
            id: order.id,
            firstName: order.firstName || 'N/A',
            lastName: order.lastName || 'N/A',
            email: order.email || 'N/A',
            phone: order.phone || 'N/A',
            address: order.address
              ? typeof order.address === 'string'
                ? JSON.parse(order.address)
                : order.address
              : { line1: 'N/A', city: 'N/A', state: 'N/A', country: 'N/A', pincode: 'N/A' },
            productName: product.title?.trim() || 'Unknown Product',
            productImage: product.image?.trim() || '/placeholder-image.jpg',
            productId: product.id?.toString().trim() || 'N/A',
            amount: (product.price && product.quantity)
              ? (product.price * product.quantity).toFixed(2)
              : '0.00',
            trackingId: order.trackingId || 'N/A',
            couponCode: order.couponCode || 'N/A',
            status: order.status || 'N/A'
          }));
        });

        setData(transformedData);
      } catch (err) {
        console.error('Error fetching orders:', err);
        setError('Failed to load orders. Please try again later.');
        setData([]);
      }
    };

    fetchData();
  }, []); // Run only once on mount

  const formatAddress = (address) => {
    if (!address) return 'N/A';
    const { line1, line2, city, state, country, pincode } = address;
    return `${line1}${line2 ? ', ' + line2 : ''}, ${city}, ${state}, ${country}, ${pincode}`;
  };

  const filteredData = data.filter(row =>
    Object.values({ ...row, address: formatAddress(row.address) }).some(
      value =>
        value &&
        value.toString().toLowerCase().includes(search.toLowerCase())
    )
  );

  const sortedData = [...filteredData].sort((a, b) => {
    if (!sortConfig.key) return 0;
    const direction = sortConfig.direction === 'asc' ? 1 : -1;
    const aValue = sortConfig.key === 'address' ? formatAddress(a[sortConfig.key]) : a[sortConfig.key]?.toString() || '';
    const bValue = sortConfig.key === 'address' ? formatAddress(b[sortConfig.key]) : b[sortConfig.key]?.toString() || '';
    return aValue.localeCompare(bValue) * direction;
  });

  const totalItems = filteredData.length;
  const totalPages = Math.ceil(totalItems / rowsPerPage);

  const handleSort = key => {
    let direction = 'asc';
    if (sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const getSortIcon = key => {
    if (sortConfig.key !== key) return <i className="bi bi-arrow-down-up ms-1"></i>;
    return sortConfig.direction === 'asc'
      ? <i className="bi bi-arrow-up ms-1"></i>
      : <i className="bi bi-arrow-down ms-1"></i>;
  };

  return (
    <div className="container">
      <div className="d-flex align-items-center mt-5 mb-4 justify-content-between">
        <h4 className="fw-normal mb-0">Order Summary</h4>
        <input
          type="text"
          className="form-control w-auto"
          placeholder="Search"
          value={search}
          onChange={e => {
            setSearch(e.target.value);
            setCurrentPage(1);
          }}
        />
      </div>

      {error && <div className="alert alert-danger">{error}</div>}

      <table className="table table-striped table-hover border rounded-3">
        <thead>
          <tr>
            <th>No</th>
            <th style={{ cursor: 'pointer' }} onClick={() => handleSort('firstName')}>
              First Name {getSortIcon('firstName')}
            </th>
            <th style={{ cursor: 'pointer' }} onClick={() => handleSort('lastName')}>
              Last Name {getSortIcon('lastName')}
            </th>
            <th style={{ cursor: 'pointer' }} onClick={() => handleSort('email')}>
              Email {getSortIcon('email')}
            </th>
            <th style={{ cursor: 'pointer' }} onClick={() => handleSort('phone')}>
              Phone {getSortIcon('phone')}
            </th>
            <th style={{ cursor: 'pointer' }} onClick={() => handleSort('address')}>
              Address {getSortIcon('address')}
            </th>
            <th style={{ cursor: 'pointer' }} onClick={() => handleSort('productName')}>
              Product Name {getSortIcon('productName')}
            </th>
            <th>Product Image</th>
            <th style={{ cursor: 'pointer' }} onClick={() => handleSort('productId')}>
              Product ID {getSortIcon('productId')}
            </th>
            <th style={{ cursor: 'pointer' }} onClick={() => handleSort('amount')}>
              Amount {getSortIcon('amount')}
            </th>
            <th style={{ cursor: 'pointer' }} onClick={() => handleSort('trackingId')}>
              Tracking ID {getSortIcon('trackingId')}
            </th>
            <th style={{ cursor: 'pointer' }} onClick={() => handleSort('couponCode')}>
              Coupon Code {getSortIcon('couponCode')}
            </th>
            <th style={{ cursor: 'pointer' }} onClick={() => handleSort('status')}>
              Status {getSortIcon('status')}
            </th>
          </tr>
        </thead>
        <tbody>
          {sortedData.slice((currentPage - 1) * rowsPerPage, currentPage * rowsPerPage).length > 0 ? (
            sortedData.slice((currentPage - 1) * rowsPerPage, currentPage * rowsPerPage).map((row, index) => (
              <tr key={`${row.id}-${row.productId}`}>
                <td>{(currentPage - 1) * rowsPerPage + index + 1}</td>
                <td>{row.firstName}</td>
                <td>{row.lastName}</td>
                <td>{row.email}</td>
                <td>{row.phone}</td>
                <td>{formatAddress(row.address)}</td>
                <td>{row.productName}</td>
                <td>
                  <img
                    src={row.productImage}
                    alt={row.productName}
                    style={{ width: '50px', height: '50px' }}
                    onError={(e) => (e.target.src = '/placeholder-image.jpg')}
                  />
                </td>
                <td>{row.productId}</td>
                <td>₹{row.amount}</td>
                <td>{row.trackingId}</td>
                <td>{row.couponCode}</td>
                <td>{row.status}</td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="13" className="text-center">{error ? 'Error loading data' : 'No entries found'}</td>
            </tr>
          )}
        </tbody>
      </table>

      <div className="d-flex justify-content-between align-items-center">
        <div className="d-flex align-items-center">
          <label className="me-2">Show</label>
          <select
            className="form-select w-auto"
            value={rowsPerPage}
            onChange={e => {
              setRowsPerPage(Number(e.target.value));
              setCurrentPage(1);
            }}
          >
            <option value="5">5</option>
            <option value="7">7</option>
            <option value="20">20</option>
          </select>
          <span className="ms-2">Entries</span>
        </div>

        <div>
          {totalItems === 0 ? 0 : (currentPage - 1) * rowsPerPage + 1} to{' '}
          {Math.min(currentPage * rowsPerPage, totalItems)} of {totalItems}
        </div>

        <div className="d-flex align-items-center">
          <div className="me-3">
            Page {currentPage} of {totalPages}
          </div>
          <button
            className="btn btn-sm btn-outline-secondary me-2"
            disabled={currentPage === 1}
            onClick={() => setCurrentPage(currentPage - 1)}
          >
            <i className="bi bi-chevron-left"></i>
          </button>
          <button
            className="btn btn-sm btn-outline-secondary"
            disabled={currentPage === totalPages}
            onClick={() => setCurrentPage(currentPage + 1)}
          >
            <i className="bi bi-chevron-right"></i>
          </button>
        </div>
      </div>
    </div>
  );
}

export default Ordersummary;