import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

function Cart() {
  const navigate = useNavigate();

  const [cartItems, setCartItems] = useState(() => {
    return JSON.parse(localStorage.getItem('cartItems')) || [];
  });

  const [couponCode, setCouponCode] = useState('');
  const [couponDiscount, setCouponDiscount] = useState(0);
  const [couponApplied, setCouponApplied] = useState(false);
  const [couponError, setCouponError] = useState('');

  // Update localStorage when cartItems changes
  useEffect(() => {
    localStorage.setItem('cartItems', JSON.stringify(cartItems));
    window.dispatchEvent(new Event('cartUpdated'));
  }, [cartItems]);

  // Function to update quantity
  const updateQuantity = (id, delta) => {
    setCartItems((prevItems) =>
      prevItems
        .map((item) =>
          item.id === id ? { ...item, quantity: Math.max(1, item.quantity + delta) } : item
        )
        .filter((item) => item.quantity > 0)
    );
  };

  // Function to remove an item
  const removeItem = (id) => {
    if (window.confirm('Are you sure you want to remove this item?')) {
      setCartItems((prevItems) => prevItems.filter((item) => item.id !== id));
    }
  };

  // Function to clear entire cart
  const clearCart = () => {
    if (window.confirm('Are you sure you want to clear all items from your cart?')) {
      setCartItems([]);
      setCouponApplied(false);
      setCouponDiscount(0);
      setCouponCode('');
    }
  };

  // Function to apply coupon
  const applyCoupon = () => {
    if (!couponCode.trim()) {
      setCouponError('Please enter a coupon code');
      return;
    }

    const coupons = {
      'WELCOME10': 0.10,
      'MEMBER20': 0.20,
      'EXPERT50': 50
    };

    const discount = coupons[couponCode.toUpperCase()];

    if (discount) {
      setCouponDiscount(discount);
      setCouponApplied(true);
      setCouponError('');
    } else {
      setCouponError('Invalid coupon code');
      setCouponApplied(false);
      setCouponDiscount(0);
    }
  };

  // Function to remove coupon
  const removeCoupon = () => {
    setCouponApplied(false);
    setCouponDiscount(0);
    setCouponCode('');
    setCouponError('');
  };

  // Calculate totals
  const subtotal = cartItems.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const shipping = cartItems.length > 0 ? 30 : 0;
  const discountAmount = typeof couponDiscount === 'number'
    ? (couponDiscount < 1 ? subtotal * couponDiscount : couponDiscount)
    : 0;
  const total = Math.max(0, subtotal + shipping - discountAmount);

  // Continue shopping
  const continueShopping = () => {
    navigate('/kai-kor/membership');
  };

  // Proceed to checkout
  const proceedToCheckout = () => {
    if (cartItems.length === 0) {
      alert('Your cart is empty');
      return;
    }
    navigate('/kai-kor/checkout');
  };

  // Empty cart message
  if (cartItems.length === 0) {
    return (
      <div className="container bg-light">
        <div className="row mx-auto mt-5 mb-5 pt-4 pb-4 text-center">
          <div className="col-lg-12">
            <div className="mb-5">
              <h2>Cart</h2>
            </div>
            <p className="fs-1 fw-lighter">Your Cart is Empty</p>
            <button
              type="button"
              className="btn btn-outline-dark mb-5"
              onClick={continueShopping}
            >
              Continue shopping
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container bg-light">
      <div class="row" data-aos="fade-up">
      <div className="col-lg-12 mt-5 mb-5 pt-4 pb-4">
        <div className="row">
          <div className="col-lg-8">
            <div className="card text-center ms-4">
              <div className="card-header bg-light text-dark">
                <h5 className="card-title">Item List</h5>
              </div>
              <div className="card-body">
                {cartItems.map((item) => (
                  <div key={item.id} className="row d-flex justify-content-between align-items-center mb-3">
                    <div className="col-3">
                      <img
                        src={item.image || '/placeholder-image.jpg'}
                        style={{
                          height: '80px',
                          width: '100px',
                          objectFit: 'cover',
                          objectPosition: 'top',
                        }}
                        className="card-img-top img-fluid"
                        alt={item.title}
                        onError={(e) => {
                          e.target.src = '/placeholder-image.jpg';
                        }}
                      />
                    </div>
                    <div className="col-4">{item.title}</div>
                    <div className="col-2 d-flex pt-1 pb-1">
                      <button
                        type="button"
                        className="btn btn-primary pt-1 pb-1"
                        onClick={() => updateQuantity(item.id, -1)}
                        disabled={item.quantity <= 1}
                      >
                        -
                      </button>
                      <span className="ms-3 me-3">{item.quantity}</span>
                      <button
                        type="button"
                        className="btn btn-primary pt-0 pb-0 mt-0 mb-0"
                        onClick={() => updateQuantity(item.id, 1)}
                      >
                        +
                      </button>
                    </div>
                    <div className="col-3 d-flex gap-3">
                      <div>₹{(item.price * item.quantity).toFixed(2)}</div>
                      <button
                        type="button"
                        className="btn btn-danger btn-sm" // Changed from btn-danger
                        onClick={() => removeItem(item.id)}
                      >
                        Remove
                      </button>
                    </div>
                  </div>
                ))}
              </div>
              <div className="card-footer">
                <div className="d-flex justify-content-between">
                  <button
                    type="button"
                    className="btn btn-outline-danger" 
                    onClick={clearCart}
                  >
                    Clear Cart
                  </button>
                  <button
                    type="button"
                    className="btn btn-primary"
                    onClick={continueShopping}
                  >
                    Continue shopping
                  </button>
                </div>
              </div>
            </div>
          </div>
          <div className="col-lg-4">
            <div className="card text-center">
              <div className="card-header bg-light text-dark">
                <h5 className="card-title">Order Summary</h5>
              </div>
              <div className="card-body">
                <div>
                  <div className="d-flex justify-content-between mb-2">
                    <div>Products ({cartItems.length})</div>
                    <div>₹{subtotal.toFixed(2)}</div>
                  </div>
                  <div className="d-flex justify-content-between mb-2">
                    <div>Shipping</div>
                    <div>₹{shipping.toFixed(2)}</div>
                  </div>
                  {couponApplied && (
                    <div className="d-flex justify-content-between mb-2">
                      <div>Coupon: {couponCode}</div>
                      <div>-₹{discountAmount.toFixed(2)}</div>
                    </div>
                  )}
                  {!couponApplied ? (
                    <div className="mb-3">
                      <div className="input-group">
                        <input
                          type="text"
                          className="form-control"
                          placeholder="Enter coupon code"
                          value={couponCode}
                          onChange={(e) => setCouponCode(e.target.value)}
                        />
                        <button
                          className="btn btn-outline-primary"
                          type="button"
                          onClick={applyCoupon}
                        >
                          Apply
                        </button>
                      </div>
                      {couponError && (
                        <small className="text-danger d-block mt-1">{couponError}</small>
                      )}
                    </div>
                  ) : (
                    <button
                      className="btn btn-outline-primary btn-sm w-100 mb-3"
                      onClick={removeCoupon}
                    >
                      Remove Coupon
                    </button>
                  )}
                  <hr />
                  <div className="d-flex justify-content-between">
                    <div>Total amount</div>
                    <div>₹{total.toFixed(2)}</div>
                  </div>
                </div>
              </div>
              <div className="card-footer">
                <button
                  type="button"
                  className="btn btn-primary w-100"
                  onClick={proceedToCheckout}
                >
                  Go to checkout
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
      </div>
    </div>
  );
}

export default Cart;