import React, { useState } from "react";
import axios from "axios";

const Eventregistration = () => {
  const initialState = {
    name: "",
    gender: "",
    phone: "",
    email: "",
    address: "",
    city: "",
    pincode: "",
    country: "",
    tshirtSize: "",
    companyName: "",
    designation: "",
    gstNo: "",
    website: "",
    businessCategory: "",
    amount: "",
  };

  const [formData, setFormData] = useState(initialState);
  const [errors, setErrors] = useState({});
  const [successMessage, setSuccessMessage] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [validationErrors, setValidationErrors] = useState({});

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((fd) => ({
      ...fd,
      [name]: value,
    }));
    if (validationErrors[name]) {
      setValidationErrors((prev) => ({ ...prev, [name]: "" }));
    }
  };

  const validateForm = () => {
    const errs = {};
    if (!formData.name.trim()) errs.name = "Name is required";
    if (!formData.gender) errs.gender = "Gender is required";
    if (!formData.phone.trim()) errs.phone = "Phone is required";
    else if (!/^\d{10}$/.test(formData.phone.replace(/\D/g, ''))) errs.phone = "Phone must be 10 digits";
    if (!formData.email.trim()) errs.email = "Email is required";
    else if (!/^\S+@\S+\.\S+$/.test(formData.email)) errs.email = "Invalid email format";
    if (formData.amount && (isNaN(formData.amount) || parseFloat(formData.amount) < 0)) {
      errs.amount = "Amount must be a valid positive number";
    }
    return errs;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const validationErrors = validateForm();
    setValidationErrors(validationErrors);

    if (Object.keys(validationErrors).length > 0) {
      return;
    }

    setIsSubmitting(true);
    setSuccessMessage("");
    setErrors({});

    try {
      const response = await axios.post("http://localhost:5000/api/eventregister/eventuser", formData);
      setSuccessMessage("Event registration submitted successfully! You will receive a confirmation email shortly.");
      setFormData(initialState);
    } catch (err) {
      console.error("Submission error:", err);
      if (err.response?.status === 400) {
        setErrors(err.response.data);
        setValidationErrors(err.response.data);
      } else {
        setErrors({ general: err.response?.data?.message || "Failed to submit registration. Please try again." });
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="container my-5">
      <div className="row justify-content-center">
        <div className="col-md-10" data-aos="fade-up">
          <div className="card shadow-lg border-0">
            <div className="card-body p-5">
              <div className="text-center mb-4">
                <h2 className="fw-bold">Event Registration</h2>
                <p className="text-muted">Complete the form below to register for the event</p>
              </div>

              {successMessage && <div className="alert alert-success">{successMessage}</div>}
              {errors.general && <div className="alert alert-danger">{errors.general}</div>}

              <form onSubmit={handleSubmit} noValidate>
                <h5 className="mb-3">Personal Information</h5>
                <div className="row mb-3">
                  <div className="col-md-6">
                    <label className="form-label fw-semibold">Full Name <span className="text-danger">*</span></label>
                    <input
                      type="text"
                      name="name"
                      className={`form-control ${validationErrors.name ? "is-invalid" : ""}`}
                      value={formData.name}
                      onChange={handleChange}
                      placeholder="Enter your full name"
                    />
                    {validationErrors.name && <div className="invalid-feedback">{validationErrors.name}</div>}
                  </div>
                  <div className="col-md-6">
                    <label className="form-label fw-semibold">Gender <span className="text-danger">*</span></label>
                    <select
                      name="gender"
                      className={`form-select ${validationErrors.gender ? "is-invalid" : ""}`}
                      value={formData.gender}
                      onChange={handleChange}
                    >
                      <option value="">Select Gender</option>
                      <option value="Male">Male</option>
                      <option value="Female">Female</option>
                    </select>
                    {validationErrors.gender && <div className="invalid-feedback">{validationErrors.gender}</div>}
                  </div>
                </div>

                <div className="row mb-3">
                  <div className="col-md-6">
                    <label className="form-label fw-semibold">Phone <span className="text-danger">*</span></label>
                    <input
                      type="tel"
                      name="phone"
                      className={`form-control ${validationErrors.phone ? "is-invalid" : ""}`}
                      value={formData.phone}
                      onChange={handleChange}
                      placeholder="10-digit phone number"
                    />
                    {validationErrors.phone && <div className="invalid-feedback">{validationErrors.phone}</div>}
                  </div>
                  <div className="col-md-6">
                    <label className="form-label fw-semibold">Email <span className="text-danger">*</span></label>
                    <input
                      type="email"
                      name="email"
                      className={`form-control ${validationErrors.email ? "is-invalid" : ""}`}
                      value={formData.email}
                      onChange={handleChange}
                      placeholder="example@email.com"
                    />
                    {validationErrors.email && <div className="invalid-feedback">{validationErrors.email}</div>}
                  </div>
                </div>

                <div className="mb-3">
                  <label className="form-label fw-semibold">Address</label>
                  <textarea
                    name="address"
                    rows="2"
                    className="form-control"
                    value={formData.address}
                    onChange={handleChange}
                    placeholder="Your complete address"
                  />
                </div>

                <div className="row mb-3">
                  <div className="col-md-4">
                    <label className="form-label fw-semibold">City</label>
                    <input
                      type="text"
                      name="city"
                      className="form-control"
                      value={formData.city}
                      onChange={handleChange}
                      placeholder="City"
                    />
                  </div>
                  <div className="col-md-4">
                    <label className="form-label fw-semibold">Pincode</label>
                    <input
                      type="text"
                      name="pincode"
                      className="form-control"
                      value={formData.pincode}
                      onChange={handleChange}
                      placeholder="6-digit pincode"
                      maxLength="6"
                    />
                  </div>
                  <div className="col-md-4">
                    <label className="form-label fw-semibold">Country</label>
                    <input
                      type="text"
                      name="country"
                      className="form-control"
                      value={formData.country}
                      onChange={handleChange}
                      placeholder="India"
                    />
                  </div>
                </div>

                <h5 className="mb-3 mt-4">Event Details</h5>
                <div className="row mb-3">
                  <div className="col-md-6">
                    <label className="form-label fw-semibold">T-Shirt Size</label>
                    <select
                      name="tshirtSize"
                      className="form-select"
                      value={formData.tshirtSize}
                      onChange={handleChange}
                    >
                      <option value="">Select Size</option>
                      {["S", "M", "L", "XL", "XXL", "XXXL"].map((size) => (
                        <option key={size} value={size}>{size}</option>
                      ))}
                    </select>
                  </div>
                  <div className="col-md-6">
                    <label className="form-label fw-semibold">Amount <span className="text-danger">*</span></label>
                    <input
                      type="number"
                      name="amount"
                      className={`form-control ${validationErrors.amount ? "is-invalid" : ""}`}
                      value={formData.amount}
                      onChange={handleChange}
                      min="0"
                    />
                    {validationErrors.amount && <div className="invalid-feedback">{validationErrors.amount}</div>}
                  </div>
                </div>

                <h5 className="mb-3 mt-4">Business Information</h5>
                <div className="row mb-3">
                  <div className="col-md-6">
                    <label className="form-label fw-semibold">Company Name</label>
                    <input
                      type="text"
                      name="companyName"
                      className="form-control"
                      value={formData.companyName}
                      onChange={handleChange}

                      placeholder="Enter company name"
                    />
                  </div>
                  <div className="col-md-6">
                    <label className="form-label fw-semibold">Designation</label>
                    <input
                      type="text"
                      name="designation"
                      className="form-control"
                      value={formData.designation}
                      onChange={handleChange}
                      placeholder="Enter your designation"
                    />
                  </div>
                </div>

                <div className="row mb-3">
                  <div className="col-md-6">
                    <label className="form-label fw-semibold">GST Number</label>
                    <input
                      type="text"
                      name="gstNo"
                      className="form-control"
                      value={formData.gstNo}
                      onChange={handleChange}
                      placeholder="Enter GST number (if applicable)"
                    />
                  </div>
                  <div className="col-md-6">
                    <label className="form-label fw-semibold">Website</label>
                    <input
                      type="url"
                      name="website"
                      className="form-control"
                      value={formData.website}
                      onChange={handleChange}
                      placeholder="https://www.example.com"
                    />
                  </div>
                </div>

                <div className="mb-4">
                  <label className="form-label fw-semibold">Business Category</label>
                  <input
                    type="text"
                    name="businessCategory"
                    className="form-control"
                    value={formData.businessCategory}
                    onChange={handleChange}
                    placeholder="Enter business category or industry"
                  />
                </div>

                <div className="d-flex justify-content-center">
                  <button
                    type="submit"
                    className="btn btn-primary btn-lg fw-bold"
                    disabled={isSubmitting}
                  >
                    {isSubmitting ? (
                      <>
                        <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                        Processing...
                      </>
                    ) : (
                      "Proceed to Payment"
                    )}
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Eventregistration;