import React, { useState } from "react";
import axios from "axios";

const steps = [
  { id: 1, title: "Contact Details", component: Step1, icon: "fas fa-user" },
  { id: 2, title: "Startup Details", component: Step2, icon: "fas fa-building" },
  { id: 3, title: "Journey & Vision", component: Step3, icon: "fas fa-road" },
  { id: 4, title: "Membership & Referral", component: Step4, icon: "fas fa-users" },
  { id: 5, title: "What's Next", component: Step5, icon: "fas fa-forward" },
];

function Membershipregistration() {
  const [currentStep, setCurrentStep] = useState(1);
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    city: "",
    startupName: "",
    startupStage: "",
    industry: "",
    journey: "",
    vision: "",
    whyJoin: "",
    referral: "",
    nextPlans: "",
  });
  const [errors, setErrors] = useState({});

  const StepComponent = steps.find((s) => s.id === currentStep).component;

  const validateStep = () => {
    const errs = {};
    if (currentStep === 1) {
      if (!formData.name) errs.name = "Full Name is required";
      if (!formData.email) errs.email = "Email is required";
      else if (!/\S+@\S+\.\S+/.test(formData.email)) errs.email = "Invalid email format";
      if (!formData.phone) errs.phone = "Phone is required";
      else if (!/^\d{10}$/.test(formData.phone)) errs.phone = "Phone must be 10 digits";
      if (!formData.city) errs.city = "City is required";
    } else if (currentStep === 2) {
      if (!formData.startupName) errs.startupName = "Startup Name is required";
      if (!formData.startupStage) errs.startupStage = "Startup Stage is required";
      else if (!["idea", "early", "growth", "scale"].includes(formData.startupStage))
        errs.startupStage = "Invalid Startup Stage";
      if (!formData.industry) errs.industry = "Industry is required";
    } else if (currentStep === 3) {
      if (!formData.journey) errs.journey = "Startup Journey is required";
      if (!formData.vision) errs.vision = "Vision is required";
    } else if (currentStep === 4) {
      if (!formData.whyJoin) errs.whyJoin = "Reason for joining is required";
    } else if (currentStep === 5) {
      if (!formData.nextPlans) errs.nextPlans = "Next Plans are required";
    }
    return errs;
  };

  const goNext = () => {
    const v = validateStep();
    if (Object.keys(v).length > 0) {
      setErrors(v);
      return;
    }
    if (currentStep < steps.length) {
      setErrors({});
      setCurrentStep(currentStep + 1);
    }
  };

  const goBack = () => {
    if (currentStep > 1) {
      setErrors({});
      setCurrentStep(currentStep - 1);
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
    setErrors((prev) => ({ ...prev, [name]: "" }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const v = validateStep();
    if (Object.keys(v).length > 0) {
      setErrors(v);
      return;
    }
    try {
      console.log("Submitting form data:", formData);
      await axios.post("http://localhost:5000/api/membershipregister/membershipuser", formData);
      alert("Form submitted successfully!");
      setFormData({
        name: "",
        email: "",
        phone: "",
        city: "",
        startupName: "",
        startupStage: "",
        industry: "",
        journey: "",
        vision: "",
        whyJoin: "",
        referral: "",
        nextPlans: "",
      });
      setCurrentStep(1);
    } catch (err) {
      console.error("Submission error:", err);
      const errorMessage = err.response?.data?.error || err.message;
      console.log("Server response:", err.response?.data);
      alert(`Submission failed: ${errorMessage}`);
    }
  };

  const progress = ((currentStep - 1) / (steps.length - 1)) * 100;

  return (
    <>
      <div className="container my-5">
        <div className="row justify-content-center">
          <div className="col-md-8 bg-white p-4 rounded shadow-sm">
            <h2 className="mb-5 text-center">Membership Pre-Registration</h2>

            {/* Step Indicators */}
            <div className="d-flex justify-content-between mb-4 position-relative flex-column flex-md-row gap-4 gap-xl-0">
              {steps.map((step) => (
                <div key={step.id} className="text-center flex-fill">
                  <div
                    className={`d-inline-block rounded-circle p-3 pt-2 pb-2 text-white mb-2 ${
                      currentStep >= step.id ? "bg-primary" : "bg-light text-dark"
                    }`}
                  >
                    <i className={step.icon}></i>
                  </div>
                  <div className={currentStep >= step.id ? "text-primary" : "text-muted"}>{step.title}</div>
                </div>
              ))}
              <div
                className="position-absolute top-50 start-0 end-0 bg-light"
                style={{ height: "2px", transform: "translateY(-50%)", zIndex: -1 }}
              />
            </div>

            {/* Progress Bar */}
            <div className="progress mb-4" style={{ height: "14px" }}>
              <div
                className="progress-bar"
                role="progressbar"
                style={{ width: `${progress}%` }}
                aria-valuenow={progress}
                aria-valuemin="0"
                aria-valuemax="100"
              >
                {Math.round(progress)}%
              </div>
            </div>

            {/* Form */}
            <form onSubmit={handleSubmit} noValidate>
              <StepComponent data={formData} onChange={handleChange} errors={errors} />

              {/* Navigation Buttons */}
              <div className="d-flex justify-content-between mt-4">
                {currentStep > 1 && (
                  <button
                    type="button"
                    className="btn btn-outline-secondary d-flex align-items-center"
                    onClick={goBack}
                  >
                    <i className="fas fa-arrow-left me-2"></i> Previous
                  </button>
                )}
                {currentStep < steps.length && (
                  <button
                    type="button"
                    className="btn btn-primary d-flex align-items-center"
                    onClick={goNext}
                  >
                    Next <i className="fas fa-arrow-right ms-2"></i>
                  </button>
                )}
                {currentStep === steps.length && (
                  <button
                    type="submit"
                    className="btn btn-success d-flex align-items-center"
                  >
                    Finish <i className="fas fa-check ms-2"></i>
                  </button>
                )}
              </div>
            </form>
          </div>
        </div>
      </div>
    </>
  );
}

function Step1({ data, onChange, errors }) {
  return (
    <>
    <div data-aos="fade-up">
      <div className="mb-4 pt-4" >
        <label htmlFor="name" className="form-label">
          <i className="fas fa-user me-2"></i>Full Name *
        </label>
        <input
          type="text"
          className={`form-control rounded ${errors.name ? "is-invalid" : ""}`}
          id="name"
          name="name"
          value={data.name}
          onChange={onChange}
          required
        />
        {errors.name && <div className="invalid-feedback">{errors.name}</div>}
      </div>
      <div className="mb-4">
        <label htmlFor="email" className="form-label">
          <i className="fas fa-envelope me-2"></i>Email *
        </label>
        <input
          type="email"
          className={`form-control rounded ${errors.email ? "is-invalid" : ""}`}
          id="email"
          name="email"
          value={data.email}
          onChange={onChange}
          required
        />
        {errors.email && <div className="invalid-feedback">{errors.email}</div>}
      </div>
      <div className="mb-4">
        <label htmlFor="phone" className="form-label">
          <i className="fas fa-phone me-2"></i>Phone *
        </label>
        <input
          type="tel"
          className={`form-control rounded ${errors.phone ? "is-invalid" : ""}`}
          id="phone"
          name="phone"
          value={data.phone}
          onChange={onChange}
          required
        />
        {errors.phone && <div className="invalid-feedback">{errors.phone}</div>}
      </div>
      <div className="mb-4">
        <label htmlFor="city" className="form-label">
          <i className="fas fa-city me-2"></i>City *
        </label>
        <input
          type="text"
          className={`form-control rounded ${errors.city ? "is-invalid" : ""}`}
          id="city"
          name="city"
          value={data.city}
          onChange={onChange}
          required
        />
        {errors.city && <div className="invalid-feedback">{errors.city}</div>}
      </div>
    </div>
    </>
  );
}

function Step2({ data, onChange, errors }) {
  return (
    <>
    <div data-aos="fade-up">
      <div className="mb-4">
        <label htmlFor="startupName" className="form-label">
          <i className="fas fa-briefcase me-2"></i>Startup Name *
        </label>
        <input
          type="text"
          className={`form-control rounded ${errors.startupName ? "is-invalid" : ""}`}
          id="startupName"
          name="startupName"
          value={data.startupName}
          onChange={onChange}
          required
        />
        {errors.startupName && <div className="invalid-feedback">{errors.startupName}</div>}
      </div>
      <div className="mb-4">
        <label htmlFor="startupStage" className="form-label">
          <i className="fas fa-chart-line me-2"></i>Startup Stage *
        </label>
        <select
          className={`form-select rounded ${errors.startupStage ? "is-invalid" : ""}`}
          id="startupStage"
          name="startupStage"
          value={data.startupStage}
          onChange={onChange}
          required
        >
          <option value="">Select</option>
          <option value="idea">Idea Stage</option>
          <option value="early">Early Stage</option>
          <option value="growth">Growth Stage</option>
          <option value="scale">Scaling</option>
        </select>
        {errors.startupStage && <div className="invalid-feedback">{errors.startupStage}</div>}
      </div>
      <div className="mb-4">
        <label htmlFor="industry" className="form-label">
          <i className="fas fa-industry me-2"></i>Industry *
        </label>
        <input
          type="text"
          className={`form-control rounded ${errors.industry ? "is-invalid" : ""}`}
          id="industry"
          name="industry"
          value={data.industry}
          onChange={onChange}
          required
        />
        {errors.industry && <div className="invalid-feedback">{errors.industry}</div>}
      </div>
      </div>
    </>
  );
}

function Step3({ data, onChange, errors }) {
  return (
    <>
    <div data-aos="fade-up">
      <div className="mb-4">
        <label htmlFor="journey" className="form-label">
          <i className="fas fa-book me-2"></i>Your Startup Journey *
        </label>
        <textarea
          className={`form-control rounded ${errors.journey ? "is-invalid" : ""}`}
          id="journey"
          name="journey"
          value={data.journey}
          onChange={onChange}
          rows={3}
          required
        />
        {errors.journey && <div className="invalid-feedback">{errors.journey}</div>}
      </div>
      <div className="mb-4">
        <label htmlFor="vision" className="form-label">
          <i className="fas fa-binoculars me-2"></i>Vision for the Future *
        </label>
        <textarea
          className={`form-control rounded ${errors.vision ? "is-invalid" : ""}`}
          id="vision"
          name="vision"
          value={data.vision}
          onChange={onChange}
          rows={3}
          required
        />
        {errors.vision && <div className="invalid-feedback">{errors.vision}</div>}
      </div>
      </div>
    </>
  );
}

function Step4({ data, onChange, errors }) {
  return (
    <>
    <div data-aos="fade-up">
      <div className="mb-4">
        <label htmlFor="whyJoin" className="form-label">
          <i className="fas fa-question-circle me-2"></i>Why do you want to join? *
        </label>
        <textarea
          className={`form-control rounded ${errors.whyJoin ? "is-invalid" : ""}`}
          id="whyJoin"
          name="whyJoin"
          value={data.whyJoin}
          onChange={onChange}
          rows={2}
          required
        />
        {errors.whyJoin && <div className="invalid-feedback">{errors.whyJoin}</div>}
      </div>
      <div className="mb-4">
        <label htmlFor="referral" className="form-label">
          <i className="fas fa-user-friends me-2"></i>Referral (if any)
        </label>
        <input
          type="text"
          className="form-control rounded"
          id="referral"
          name="referral"
          value={data.referral}
          onChange={onChange}
        />
      </div>
      </div>
    </>
  );
}

function Step5({ data, onChange, errors }) {
  return (
    <>
    <div data-aos="fade-up">
      <div className="mb-4">
        <label htmlFor="nextPlans" className="form-label">
          <i className="fas fa-list-ul me-2"></i>Next Plans *
        </label>
        <textarea
          className={`form-control rounded ${errors.nextPlans ? "is-invalid" : ""}`}
          id="nextPlans"
          name="nextPlans"
          value={data.nextPlans}
          onChange={onChange}
          rows={3}
          required
        />
        {errors.nextPlans && <div className="invalid-feedback">{errors.nextPlans}</div>}
      </div>
      </div>
    </>
  );
}

export default Membershipregistration;