import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import 'bootstrap/dist/css/bootstrap.min.css';

function Orderprocessed() {
  const navigate = useNavigate();
  const location = useLocation();
  const [orderData, setOrderData] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const data = location.state?.order || null;
    console.log('Order data from location.state:', data);
    
    if (data && data.trackingId && data.orderedItems && Array.isArray(data.orderedItems)) {
      setOrderData({
        ...data,
        orderedItems: data.orderedItems.map(item => ({
          ...item,
          totalPrice: item.price * item.quantity
        }))
      });
      localStorage.setItem('lastOrder', JSON.stringify(data));
    } else {
      const fallback = JSON.parse(localStorage.getItem('lastOrder'));
      if (fallback && fallback.trackingId && Array.isArray(fallback.orderedItems)) {
        setOrderData(fallback);
      } else {
        setOrderData(null);
      }
    }
    setLoading(false);
  }, [location.state]);

  const clearStorageAndCart = () => {
    localStorage.removeItem('cartItems');
    localStorage.removeItem('lastOrder');
    window.dispatchEvent(new Event('cartUpdated'));
  };

  const handleContinueShopping = () => {
    clearStorageAndCart();
    navigate('/kai-kor/membership');
  };

  const handleViewOrder = () => {
    if (orderData) {
      navigate('/kai-kor/orderprocessed', { state: { order: orderData } });
    }
  };

  const handleDownloadInvoice = () => {
    if (orderData) {
      const invoiceData = {
        trackingId: orderData.trackingId,
        total: orderData.total,
        items: orderData.orderedItems,
        customer: {
          name: `${orderData.firstName} ${orderData.lastName}`,
          email: orderData.email,
          phone: orderData.phone
        }
      };
      const blob = new Blob([JSON.stringify(invoiceData, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `invoice-${orderData.trackingId}.json`;
      a.click();
      URL.revokeObjectURL(url);
      alert('Invoice downloaded! In production, this would generate a PDF.');
    }
  };

  if (loading) {
    return (
      <div className="container my-5">
        <div className="row justify-content-center">
          <div className="col-lg-6 text-center">
            <p>Loading your order confirmation...</p>
          </div>
        </div>
      </div>
    );
  }

  if (!orderData) {
    return (
      <div className="container my-5">
        <div className="row justify-content-center">
          <div className="col-lg-6 text-center">
            <div className="card border-0 shadow">
              <div className="card-body text-center p-5">
                <h4 className="mb-3">Order Not Found</h4>
                <p className="text-muted mb-4">
                  We couldn't find your order details. Please complete the checkout process or contact support.
                </p>
                <div className="d-flex gap-2 justify-content-center flex-wrap">
                  <button
                    className="btn btn-primary"
                    onClick={() => navigate('/kai-kor/checkout')}
                  >
                    Go to Checkout
                  </button>
                  <button
                    className="btn btn-outline-primary"
                    onClick={() => navigate('/kai-kor/membership')}
                  >
                    Back to Membership
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  const { 
    firstName, 
    lastName, 
    email, 
    phone, 
    address, 
    trackingId, 
    paymentMethod, 
    paymentDetails,
    orderedItems, 
    subtotal, 
    shipping, 
    total,
    orderDate,
    couponCode,
    discountAmount
  } = orderData;

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('en-IN', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  return (
    <div className="container my-5 bg-light">
      <div className="row justify-content-center mb-5">
        <div className="col-lg-8 text-center">
          <h1 className="display-4 fw-bold mb-3">Order Confirmed!</h1>
          <p className="lead text-muted">
            Thank you for your purchase! Your order has been successfully processed.
          </p>
          <div className="alert alert-light">
            <strong>Order ID:</strong> <code>{trackingId}</code>
            {orderDate && (
              <>
                <br />
                <strong>Placed on:</strong> {formatDate(orderDate)}
              </>
            )}
          </div>
        </div>
      </div>

      <div className="row g-4">
        <div className="col-lg-8">
          <div className="card shadow-sm h-100">
            <div className="card-header bg-light text-dark">
              <h5 className="mb-0">Order Details</h5>
            </div>
            <div className="card-body">
              <div className="row mb-4">
                <div className="col-md-6">
                  <h6>Customer Information</h6>
                  <div className="info-item">
                    <strong>Name:</strong> {firstName} {lastName}
                  </div>
                  <div className="info-item">
                    <strong>Email:</strong> {email}
                  </div>
                  <div className="info-item">
                    <strong>Phone:</strong> {phone}
                  </div>
                  <div className="info-item">
                    <strong>Payment Method:</strong> {paymentMethod.toUpperCase()}
                  </div>
                  {paymentDetails?.nameOnCard && (
                    <div className="info-item">
                      <strong>Cardholder:</strong> {paymentDetails.nameOnCard}
                    </div>
                  )}
                </div>
                <div className="col-md-6">
                  <h6>Shipping Address</h6>
                  <div className="info-item">
                    <strong>Address:</strong>
                    <div className="mt-1">
                      <div>{address?.line1 || address}</div>
                      {address?.line2 && <div>{address.line2}</div>}
                      {address?.city && <div>{address.city}, {address.state}</div>}
                      {address?.pincode && <div>{address.pincode}</div>}
                      <div className="text-muted small mt-1">
                        {address?.country || 'India'}
                      </div>
                    </div>
                  </div>
                  <div className="info-item">
                    <strong>Order Status:</strong> <span className="badge bg-light text-dark ms-2">Confirmed</span>
                  </div>
                  <div className="info-item">
                    <strong>Estimated Delivery:</strong> <span>2-3 business days</span>
                  </div>
                </div>
              </div>
              <h6 className="mb-3">Ordered Items ({orderedItems.length})</h6>
              <div className="order-items-list">
                {orderedItems.map((item) => (
                  <div key={item.id} className="order-item-card mb-3">
                    <div className="row align-items-center">
                      <div className="col-md-2">
                        <img
                          src={item.image || '/placeholder.jpg'}
                          alt={item.title}
                          className="img-fluid rounded shadow-sm"
                          style={{ 
                            height: '80px', 
                            width: '100%', 
                            objectFit: 'cover' 
                          }}
                          onError={(e) => {
                            e.target.src = '/placeholder.jpg';
                          }}
                        />
                      </div>
                      <div className="col-md-6">
                        <h6 className="mb-1">{item.title}</h6>
                        <p className="text-muted small mb-1">
                          {item.category || 'Expert Session'}
                        </p>
                        <div className="mb-1">
                          <small className="text-muted">
                            Qty: {item.quantity} × ₹{item.price}
                          </small>
                        </div>
                        {item.originalPrice && (
                          <small className="text-decoration-line-through text-muted">
                            ₹{item.originalPrice}
                          </small>
                        )}
                      </div>
                      <div className="col-md-4 text-md-end">
                        <div className="fw-bold fs-5">
                          ₹{(item.price * item.quantity).toFixed(2)}
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
        <div className="col-lg-4">
          <div className="card shadow-sm sticky-top" style={{ top: '20px' }}>
            <div className="card-header bg-light text-dark">
              <h5 className="mb-0">Order Summary</h5>
            </div>
            <div className="card-body">
              <div className="price-breakdown">
                <div className="d-flex justify-content-between mb-2">
                  <span>Subtotal ({orderedItems.length} items)</span>
                  <span>₹{subtotal?.toFixed(2) || '0.00'}</span>
                </div>
                <div className="d-flex justify-content-between mb-2">
                  <span>Shipping</span>
                  <span>₹{shipping?.toFixed(2) || '0.00'}</span>
                </div>
                {couponCode && (
                  <div className="d-flex justify-content-between mb-2">
                    <span>Coupon: {couponCode}</span>
                    <span>-₹{discountAmount?.toFixed(2) || '0.00'}</span>
                  </div>
                )}
                <hr />
                <div className="d-flex justify-content-between mb-3">
                  <strong>Total Amount</strong>
                  <strong>₹{total?.toFixed(2) || '0.00'}</strong>
                </div>
              </div>
              <div className="action-buttons">
                <button
                  className="btn btn-outline-primary w-100 mb-2"
                  onClick={handleViewOrder}
                >
                  Track Order
                </button>
                <button
                  className="btn btn-outline-primary w-100 mb-2"
                  onClick={handleDownloadInvoice}
                >
                  Download Invoice
                </button>
                <button
                  className="btn btn-primary w-100"
                  onClick={handleContinueShopping}
                >
                  Continue Shopping
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Orderprocessed;