import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import axios from 'axios';
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap-icons/font/bootstrap-icons.css';

function Customerdetails() {
  const location = useLocation();
  const [data, setData] = useState([]);
  const [search, setSearch] = useState('');
  const [rowsPerPage, setRowsPerPage] = useState(5);
  const [currentPage, setCurrentPage] = useState(1);
  const [sortConfig, setSortConfig] = useState({ key: null, direction: 'asc' });
  const [totalItems, setTotalItems] = useState(0);
  const [editId, setEditId] = useState(null);
  const [editFormData, setEditFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    address: { line1: '', line2: '', city: '', state: '', country: '', pincode: '' },
    trackingId: '',
    paymentMethod: '',
    couponCode: '',
    discountAmount: '',
    status: ''
  });

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await axios.get(
          `http://localhost:5000/api/orders/orderuser?page=${currentPage}&size=${rowsPerPage}`
        );
        const { data: fetchedData, total } = response.data;
        setData(fetchedData);
        setTotalItems(total);
      } catch (err) {
        console.error('Error fetching customers:', err);
        alert('Failed to fetch customers');
      }
    };
    fetchData();
  }, [currentPage, rowsPerPage, location.state]);

  const handleDelete = async (id) => {
    try {
      await axios.delete(`http://localhost:5000/api/orders/orderuser/${id}`);
      setData(data.filter(item => item.id !== id));
      setTotalItems(prev => prev - 1);
    } catch (err) {
      console.error('Error deleting customer:', err);
      alert('Failed to delete customer');
    }
  };

  const handleEdit = (id) => {
    const customer = data.find(item => item.id === id);
    if (customer) {
      setEditId(id);
      setEditFormData({
        firstName: customer.firstName || '',
        lastName: customer.lastName || '',
        email: customer.email || '',
        phone: customer.phone || '',
        address: typeof customer.address === 'string' ? JSON.parse(customer.address) : customer.address || {
          line1: '',
          line2: '',
          city: '',
          state: '',
          country: '',
          pincode: ''
        },
        trackingId: customer.trackingId || '',
        paymentMethod: customer.paymentMethod || '',
        couponCode: customer.couponCode || '',
        discountAmount: customer.discountAmount || '',
        status: customer.status || ''
      });
    }
  };

  const handleEditSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await axios.put(`http://localhost:5000/api/orders/orderuser/${editId}`, editFormData);
      setData(data.map(item => (item.id === editId ? { ...response.data } : item)));
      setEditId(null);
      setEditFormData({
        firstName: '',
        lastName: '',
        email: '',
        phone: '',
        address: { line1: '', line2: '', city: '', state: '', country: '', pincode: '' },
        trackingId: '',
        paymentMethod: '',
        couponCode: '',
        discountAmount: '',
        status: ''
      });
      document.getElementById('editModal').classList.remove('show');
      document.body.classList.remove('modal-open');
      document.querySelector('.modal-backdrop')?.remove();
    } catch (err) {
      console.error('Error updating customer:', err);
      alert('Failed to update customer');
    }
  };

  const handleEditChange = (e, nestedField = null) => {
    if (nestedField) {
      setEditFormData({
        ...editFormData,
        address: { ...editFormData.address, [nestedField]: e.target.value }
      });
    } else {
      setEditFormData({ ...editFormData, [e.target.name]: e.target.value });
    }
  };

  const formatAddress = (address) => {
    if (!address) return 'N/A';
    if (typeof address === 'string') {
      try {
        address = JSON.parse(address);
      } catch {
        return address;
      }
    }
    const { line1, line2, city, state, country, pincode } = address;
    return `${line1}${line2 ? ', ' + line2 : ''}, ${city}, ${state}, ${country}, ${pincode}`;
  };

  const filteredData = data.filter(
    (row) =>
      (row.firstName?.toLowerCase().includes(search.toLowerCase())) ||
      (row.lastName?.toLowerCase().includes(search.toLowerCase())) ||
      (row.email?.toLowerCase().includes(search.toLowerCase())) ||
      (row.phone?.toLowerCase().includes(search.toLowerCase())) ||
      (formatAddress(row.address)?.toLowerCase().includes(search.toLowerCase())) ||
      (row.trackingId?.toLowerCase().includes(search.toLowerCase())) ||
      (row.paymentMethod?.toLowerCase().includes(search.toLowerCase())) ||
      (row.couponCode?.toLowerCase().includes(search.toLowerCase())) ||
      (row.status?.toLowerCase().includes(search.toLowerCase()))
  );

  const sortedData = [...filteredData].sort((a, b) => {
    if (!sortConfig.key) return 0;
    const direction = sortConfig.direction === 'asc' ? 1 : -1;
    const aValue = sortConfig.key === 'address' ? formatAddress(a[sortConfig.key]) : a[sortConfig.key] || '';
    const bValue = sortConfig.key === 'address' ? formatAddress(b[sortConfig.key]) : b[sortConfig.key] || '';
    return aValue.localeCompare(bValue) * direction;
  });

  const totalPages = Math.ceil(totalItems / rowsPerPage);
  const paginatedData = sortedData;

  const handleSort = (key) => {
    setSortConfig(prev => ({
      key,
      direction: prev.key === key && prev.direction === 'asc' ? 'desc' : 'asc',
    }));
  };

  const getSortIcon = (key) => {
    if (sortConfig.key !== key) return <i className="bi bi-arrow-down-up ms-1"></i>;
    return sortConfig.direction === 'asc' ? (
      <i className="bi bi-arrow-up ms-1"></i>
    ) : (
      <i className="bi bi-arrow-down ms-1"></i>
    );
  };

  return (
    <div className="container">
      <div className="d-flex align-items-center mt-5 mb-4 justify-content-between">
        <h4 className="fw-normal mb-0">Customer Details</h4>
        <input
          type="text"
          className="form-control w-auto"
          placeholder="Search by name, email, phone, address, tracking ID, payment method, coupon, or status"
          value={search}
          onChange={(e) => {
            setSearch(e.target.value);
            setCurrentPage(1);
          }}
        />
      </div>

      <table className="table table-striped table-hover border rounded-3">
        <thead>
          <tr>
            <th scope="col">No</th>
            <th scope="col" style={{ cursor: 'pointer' }} onClick={() => handleSort('firstName')}>
              First Name {getSortIcon('firstName')}
            </th>
            <th scope="col" style={{ cursor: 'pointer' }} onClick={() => handleSort('lastName')}>
              Last Name {getSortIcon('lastName')}
            </th>
            <th scope="col" style={{ cursor: 'pointer' }} onClick={() => handleSort('email')}>
              Email {getSortIcon('email')}
            </th>
            <th scope="col" style={{ cursor: 'pointer' }} onClick={() => handleSort('phone')}>
              Phone {getSortIcon('phone')}
            </th>
            <th scope="col" style={{ cursor: 'pointer' }} onClick={() => handleSort('address')}>
              Address {getSortIcon('address')}
            </th>
            <th scope="col" style={{ cursor: 'pointer' }} onClick={() => handleSort('trackingId')}>
              Tracking ID {getSortIcon('trackingId')}
            </th>
            <th scope="col" style={{ cursor: 'pointer' }} onClick={() => handleSort('paymentMethod')}>
              Payment Method {getSortIcon('paymentMethod')}
            </th>
            <th scope="col" style={{ cursor: 'pointer' }} onClick={() => handleSort('couponCode')}>
              Coupon Code {getSortIcon('couponCode')}
            </th>
            <th scope="col" style={{ cursor: 'pointer' }} onClick={() => handleSort('status')}>
              Status {getSortIcon('status')}
            </th>
            <th scope="col">Actions</th>
          </tr>
        </thead>
        <tbody>
          {paginatedData.length > 0 ? (
            paginatedData.map((row, index) => (
              <tr key={row.id}>
                <td>{(currentPage - 1) * rowsPerPage + index + 1}</td>
                <td>{row.firstName}</td>
                <td>{row.lastName || 'N/A'}</td>
                <td>{row.email}</td>
                <td>{row.phone}</td>
                <td>{formatAddress(row.address)}</td>
                <td>{row.trackingId}</td>
                <td>{row.paymentMethod}</td>
                <td>{row.couponCode || 'N/A'}</td>
                <td>{row.status || 'N/A'}</td>
                <td>
                  <button
                    className="btn btn-sm btn-outline-primary me-2"
                    onClick={() => handleEdit(row.id)}
                    title="Edit"
                    data-bs-toggle="modal"
                    data-bs-target="#editModal"
                  >
                    <i className="bi bi-pencil"></i>
                  </button>
                  <button
                    className="btn btn-sm btn-outline-danger"
                    onClick={() => handleDelete(row.id)}
                    title="Delete"
                  >
                    <i className="bi bi-trash"></i>
                  </button>
                </td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="11" className="text-center">
                No entries found
              </td>
            </tr>
          )}
        </tbody>
      </table>

      {/* Edit Modal */}
      <div className="modal fade" id="editModal" tabIndex="-1" aria-labelledby="editModalLabel" aria-hidden="true">
        <div className="modal-dialog">
          <div className="modal-content">
            <div className="modal-header">
              <h5 className="modal-title" id="editModalLabel">Edit Customer</h5>
              <button
                type="button"
                className="btn-close"
                data-bs-dismiss="modal"
                aria-label="Close"
                onClick={() => {
                  setEditId(null);
                  setEditFormData({
                    firstName: '',
                    lastName: '',
                    email: '',
                    phone: '',
                    address: { line1: '', line2: '', city: '', state: '', country: '', pincode: '' },
                    trackingId: '',
                    paymentMethod: '',
                    couponCode: '',
                    discountAmount: '',
                    status: ''
                  });
                }}
              ></button>
            </div>
            <form onSubmit={handleEditSubmit}>
              <div className="modal-body">
                <div className="mb-3">
                  <label htmlFor="editFirstName" className="form-label">First Name</label>
                  <input
                    type="text"
                    className="form-control"
                    id="editFirstName"
                    name="firstName"
                    value={editFormData.firstName}
                    onChange={handleEditChange}
                    placeholder="Enter First Name"
                    required
                  />
                </div>
                <div className="mb-3">
                  <label htmlFor="editLastName" className="form-label">Last Name</label>
                  <input
                    type="text"
                    className="form-control"
                    id="editLastName"
                    name="lastName"
                    value={editFormData.lastName}
                    onChange={handleEditChange}
                    placeholder="Enter Last Name"
                  />
                </div>
                <div className="mb-3">
                  <label htmlFor="editEmail" className="form-label">Email</label>
                  <input
                    type="email"
                    className="form-control"
                    id="editEmail"
                    name="email"
                    value={editFormData.email}
                    onChange={handleEditChange}
                    placeholder="Enter Email"
                    required
                  />
                </div>
                <div className="mb-3">
                  <label htmlFor="editPhone" className="form-label">Phone</label>
                  <input
                    type="text"
                    className="form-control"
                    id="editPhone"
                    name="phone"
                    value={editFormData.phone}
                    onChange={handleEditChange}
                    placeholder="Enter Phone"
                    required
                  />
                </div>
                <div className="mb-3">
                  <label className="form-label">Address</label>
                  <div className="row">
                    <div className="col-md-6 mb-3">
                      <input
                        type="text"
                        className="form-control"
                        placeholder="Line 1"
                        value={editFormData.address.line1}
                        onChange={(e) => handleEditChange(e, 'line1')}
                        required
                      />
                    </div>
                    <div className="col-md-6 mb-3">
                      <input
                        type="text"
                        className="form-control"
                        placeholder="Line 2 (Optional)"
                        value={editFormData.address.line2}
                        onChange={(e) => handleEditChange(e, 'line2')}
                      />
                    </div>
                    <div className="col-md-6 mb-3">
                      <input
                        type="text"
                        className="form-control"
                        placeholder="City"
                        value={editFormData.address.city}
                        onChange={(e) => handleEditChange(e, 'city')}
                        required
                      />
                    </div>
                    <div className="col-md-6 mb-3">
                      <input
                        type="text"
                        className="form-control"
                        placeholder="State"
                        value={editFormData.address.state}
                        onChange={(e) => handleEditChange(e, 'state')}
                        required
                      />
                    </div>
                    <div className="col-md-6 mb-3">
                      <input
                        type="text"
                        className="form-control"
                        placeholder="Country"
                        value={editFormData.address.country}
                        onChange={(e) => handleEditChange(e, 'country')}
                        required
                      />
                    </div>
                    <div className="col-md-6 mb-3">
                      <input
                        type="text"
                        className="form-control"
                        placeholder="Pincode"
                        value={editFormData.address.pincode}
                        onChange={(e) => handleEditChange(e, 'pincode')}
                        required
                      />
                    </div>
                  </div>
                </div>
                <div className="mb-3">
                  <label htmlFor="editTrackingId" className="form-label">Tracking ID</label>
                  <input
                    type="text"
                    className="form-control"
                    id="editTrackingId"
                    name="trackingId"
                    value={editFormData.trackingId}
                    onChange={handleEditChange}
                    placeholder="Enter Tracking ID"
                    required
                  />
                </div>
                <div className="mb-3">
                  <label htmlFor="editPaymentMethod" className="form-label">Payment Method</label>
                  <input
                    type="text"
                    className="form-control"
                    id="editPaymentMethod"
                    name="paymentMethod"
                    value={editFormData.paymentMethod}
                    onChange={handleEditChange}
                    placeholder="Enter Payment Method"
                    required
                  />
                </div>
                <div className="mb-3">
                  <label htmlFor="editCouponCode" className="form-label">Coupon Code</label>
                  <input
                    type="text"
                    className="form-control"
                    id="editCouponCode"
                    name="couponCode"
                    value={editFormData.couponCode}
                    onChange={handleEditChange}
                    placeholder="Enter Coupon Code"
                  />
                </div>
                <div className="mb-3">
                  <label htmlFor="editStatus" className="form-label">Status</label>
                  <input
                    type="text"
                    className="form-control"
                    id="editStatus"
                    name="status"
                    value={editFormData.status}
                    onChange={handleEditChange}
                    placeholder="Enter Status"
                  />
                </div>
              </div>
              <div className="modal-footer">
                <button
                  type="button"
                  className="btn btn-secondary"
                  data-bs-dismiss="modal"
                  onClick={() => {
                    setEditId(null);
                    setEditFormData({
                      firstName: '',
                      lastName: '',
                      email: '',
                      phone: '',
                      address: { line1: '', line2: '', city: '', state: '', country: '', pincode: '' },
                      trackingId: '',
                      paymentMethod: '',
                      couponCode: '',
                      discountAmount: '',
                      status: ''
                    });
                  }}
                >
                  Cancel
                </button>
                <button type="submit" className="btn btn-primary">Save</button>
              </div>
            </form>
          </div>
        </div>
      </div>

      <div className="d-flex justify-content-between align-items-center">
        <div className="d-flex align-items-center">
          <label className="me-2">Show</label>
          <select
            className="form-select w-auto"
            value={rowsPerPage}
            onChange={(e) => {
              setRowsPerPage(Number(e.target.value));
              setCurrentPage(1);
            }}
          >
            <option value="5">5</option>
            <option value="10">10</option>
            <option value="20">20</option>
          </select>
          <span className="ms-2">Entries</span>
        </div>

        <div>
          Showing {data.length === 0 ? 0 : (currentPage - 1) * rowsPerPage + 1} to{' '}
          {(currentPage - 1) * rowsPerPage + data.length} of {totalItems} entries
        </div>

        <div className="d-flex align-items-center">
          <div className="me-3">
            Page {currentPage} of {totalPages}
          </div>
          <button
            className="btn btn-sm btn-outline-secondary me-2"
            disabled={currentPage === 1}
            onClick={() => setCurrentPage(prev => prev - 1)}
          >
            <i className="bi bi-chevron-left"></i>
          </button>
          <button
            className="btn btn-sm btn-outline-secondary"
            disabled={currentPage === totalPages}
            onClick={() => setCurrentPage(prev => prev + 1)}
          >
            <i className="bi bi-chevron-right"></i>
          </button>
        </div>
      </div>
    </div>
  );
}

export default Customerdetails;