import React, { useEffect, useState } from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap-icons/font/bootstrap-icons.css';
import axios from 'axios';

function EventSchedule() {
  const [events, setEvents] = useState([]);
  const [form, setForm] = useState({
    id: null,
    day: '',
    time: '',
    title: '',
    speaker: '',
    role: '',
    location: '',
    venue: '',
    available_seats: 2000,
  });
  const [search, setSearch] = useState('');
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [currentPage, setCurrentPage] = useState(1);
  const [sortConfig, setSortConfig] = useState({ key: null, direction: 'asc' });
  const [totalItems, setTotalItems] = useState(0);
  const [showModal, setShowModal] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    fetchEvents();
  }, [currentPage, rowsPerPage]);

  const fetchEvents = async () => {
    setIsLoading(true);
    try {
      const response = await axios.get(
        `http://localhost:5000/api/events/eventsuser?page=${currentPage}&size=${rowsPerPage}`
      );
      if (!response.data || typeof response.data.total !== 'number' || !Array.isArray(response.data.data)) {
        throw new Error('Invalid response structure from server');
      }
      const { data: fetchedData, total } = response.data;
      setEvents(fetchedData);
      setTotalItems(total);
    } catch (err) {
      console.error('Error fetching events:', {
        message: err.message,
        status: err.response?.status,
        data: err.response?.data,
        config: err.config,
      });
      alert('Failed to fetch events. Please check the server or try again later.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    try {
      const requiredFields = ['day', 'time', 'title', 'speaker', 'role', 'location', 'venue', 'available_seats'];
      const missingFields = requiredFields.filter((field) => !form[field]);
      if (missingFields.length > 0) {
        throw new Error(`Missing required fields: ${missingFields.join(', ')}`);
      }
      const method = form.id ? 'PUT' : 'POST';
      const url = form.id
        ? `http://localhost:5000/api/events/eventsuser/${form.id}`
        : 'http://localhost:5000/api/events/eventsuser';
      await axios({
        method,
        url,
        data: form,
        headers: { 'Content-Type': 'application/json' },
      });
      fetchEvents();
      setForm({
        id: null,
        day: '',
        time: '',
        title: '',
        speaker: '',
        role: '',
        location: '',
        venue: '',
        available_seats: 2000,
      });
      setShowModal(false);
    } catch (err) {
      console.error('Error saving event:', {
        message: err.message,
        status: err.response?.status,
        data: err.response?.data,
        config: err.config,
      });
      alert(`Failed to ${form.id ? 'update' : 'add'} event: ${err.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleEdit = (event) => {
    setForm(event);
    setShowModal(true);
  };

  const handleDelete = async (id) => {
    setIsLoading(true);
    try {
      await axios.delete(`http://localhost:5000/api/events/eventsuser/${id}`);
      setEvents(events.filter((item) => item.id !== id));
      setTotalItems((prev) => prev - 1);
    } catch (err) {
      console.error('Error deleting event:', {
        message: err.message,
        status: err.response?.status,
        data: err.response?.data,
      });
      alert('Failed to delete event. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const filteredData = events.filter((row) =>
    ['day', 'time', 'title', 'speaker', 'role', 'location', 'venue', 'available_seats'].some((key) =>
      row[key]?.toString().toLowerCase().includes(search.toLowerCase())
    )
  );

  const sortedData = [...filteredData].sort((a, b) => {
    if (!sortConfig.key) return 0;
    const direction = sortConfig.direction === 'asc' ? 1 : -1;
    const aValue = a[sortConfig.key] ? a[sortConfig.key].toString() : '';
    const bValue = b[sortConfig.key] ? b[sortConfig.key].toString() : '';
    return aValue.localeCompare(bValue) * direction;
  });

  const totalPages = Math.ceil(totalItems / rowsPerPage);
  const paginatedData = sortedData;

  const handleSort = (key) => {
    setSortConfig((prev) => ({
      key,
      direction: prev.key === key && prev.direction === 'asc' ? 'desc' : 'asc',
    }));
  };

  const getSortIcon = (key) => {
    if (sortConfig.key !== key) return <i className="bi bi-arrow-down-up ms-1"></i>;
    return sortConfig.direction === 'asc' ? (
      <i className="bi bi-arrow-up ms-1"></i>
    ) : (
      <i className="bi bi-arrow-down ms-1"></i>
    );
  };

  return (
    <div className="container mt-5">
      {isLoading && (
        <div className="text-center my-3">
          <div className="spinner-border text-primary" role="status">
            <span className="visually-hidden">Loading...</span>
          </div>
        </div>
      )}
      <div className="d-flex align-items-center mb-4 justify-content-between">
        <h4 className="fw-normal mb-0">Admin Event Schedule</h4>
        <input
          type="text"
          className="form-control w-auto"
          placeholder="Search by day, time, title, etc."
          value={search}
          onChange={(e) => {
            setSearch(e.target.value);
            setCurrentPage(1);
          }}
        />
      </div>

      <button
        className="btn btn-primary mb-4"
        onClick={() => {
          setForm({
            id: null,
            day: '',
            time: '',
            title: '',
            speaker: '',
            role: '',
            location: '',
            venue: '',
            available_seats: 2000,
          });
          setShowModal(true);
        }}
        disabled={isLoading}
      >
        Add Event
      </button>

      <div className="table-responsive">
        <table className="table table-striped table-hover border rounded-3">
          <thead>
            <tr>
              <th scope="col">No</th>
              <th scope="col" style={{ cursor: 'pointer' }} onClick={() => handleSort('day')}>
                Day {getSortIcon('day')}
              </th>
              <th scope="col" style={{ cursor: 'pointer' }} onClick={() => handleSort('time')}>
                Time {getSortIcon('time')}
              </th>
              <th scope="col" style={{ cursor: 'pointer' }} onClick={() => handleSort('title')}>
                Title {getSortIcon('title')}
              </th>
              <th scope="col" style={{ cursor: 'pointer' }} onClick={() => handleSort('speaker')}>
                Speaker {getSortIcon('speaker')}
              </th>
              <th scope="col" style={{ cursor: 'pointer' }} onClick={() => handleSort('role')}>
                Role {getSortIcon('role')}
              </th>
              <th scope="col" style={{ cursor: 'pointer' }} onClick={() => handleSort('location')}>
                Location {getSortIcon('location')}
              </th>
              <th scope="col" style={{ cursor: 'pointer' }} onClick={() => handleSort('venue')}>
                Venue {getSortIcon('venue')}
              </th>
              <th scope="col" style={{ cursor: 'pointer' }} onClick={() => handleSort('available_seats')}>
                Available Seats {getSortIcon('available_seats')}
              </th>
              <th scope="col">Actions</th>
            </tr>
          </thead>
          <tbody>
            {paginatedData.length > 0 ? (
              paginatedData.map((row, index) => (
                <tr key={row.id}>
                  <td>{(currentPage - 1) * rowsPerPage + index + 1}</td>
                  <td>{row.day}</td>
                  <td>{row.time}</td>
                  <td>{row.title}</td>
                  <td>{row.speaker}</td>
                  <td>{row.role}</td>
                  <td>{row.location}</td>
                  <td>{row.venue}</td>
                  <td>{row.available_seats}</td>
                  <td>
                    <button
                      className="btn btn-sm btn-outline-primary me-2"
                      onClick={() => handleEdit(row)}
                      title="Edit"
                      disabled={isLoading}
                    >
                      <i className="bi bi-pencil"></i>
                    </button>
                    <button
                      className="btn btn-sm btn-outline-danger"
                      onClick={() => handleDelete(row.id)}
                      title="Delete"
                      disabled={isLoading}
                    >
                      <i className="bi bi-trash"></i>
                    </button>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan="10" className="text-center">
                  No entries found
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      <div className={`modal fade ${showModal ? 'show d-block' : ''}`} tabIndex="-1">
        <div className="modal-dialog">
          <div className="modal-content">
            <div className="modal-header">
              <h5 className="modal-title">{form.id ? 'Edit Event' : 'Add Event'}</h5>
              <button
                type="button"
                className="btn-close"
                onClick={() => setShowModal(false)}
                disabled={isLoading}
              ></button>
            </div>
            <div className="modal-body">
              <form onSubmit={handleSubmit}>
                <div className="mb-3">
                  <label className="form-label">Day (1-3)</label>
                  <input
                    type="number"
                    className="form-control"
                    name="day"
                    value={form.day}
                    onChange={handleChange}
                    required
                    min="1"
                    max="3"
                    disabled={isLoading}
                  />
                </div>
                <div className="mb-3">
                  <label className="form-label">Time</label>
                  <input
                    type="text"
                    className="form-control"
                    name="time"
                    value={form.time}
                    onChange={handleChange}
                    required
                    disabled={isLoading}
                  />
                </div>
                <div className="mb-3">
                  <label className="form-label">Title</label>
                  <input
                    type="text"
                    className="form-control"
                    name="title"
                    value={form.title}
                    onChange={handleChange}
                    required
                    disabled={isLoading}
                  />
                </div>
                <div className="mb-3">
                  <label className="form-label">Speaker</label>
                  <input
                    type="text"
                    className="form-control"
                    name="speaker"
                    value={form.speaker}
                    onChange={handleChange}
                    required
                    disabled={isLoading}
                  />
                </div>
                <div className="mb-3">
                  <label className="form-label">Role</label>
                  <input
                    type="text"
                    className="form-control"
                    name="role"
                    value={form.role}
                    onChange={handleChange}
                    required
                    disabled={isLoading}
                  />
                </div>
                <div className="mb-3">
                  <label className="form-label">Location</label>
                  <input
                    type="text"
                    className="form-control"
                    name="location"
                    value={form.location}
                    onChange={handleChange}
                    required
                    disabled={isLoading}
                  />
                </div>
                <div className="mb-3">
                  <label className="form-label">Venue</label>
                  <input
                    type="text"
                    className="form-control"
                    name="venue"
                    value={form.venue}
                    onChange={handleChange}
                    required
                    disabled={isLoading}
                  />
                </div>
                <div className="mb-3">
                  <label className="form-label">Available Seats</label>
                  <input
                    type="number"
                    className="form-control"
                    name="available_seats"
                    value={form.available_seats}
                    onChange={handleChange}
                    required
                    min="0"
                    disabled={isLoading}
                  />
                </div>
                <div className="modal-footer">
                  <button
                    type="button"
                    className="btn btn-secondary"
                    onClick={() => setShowModal(false)}
                    disabled={isLoading}
                  >
                    Close
                  </button>
                  <button type="submit" className="btn btn-primary" disabled={isLoading}>
                    {isLoading ? 'Saving...' : form.id ? 'Update' : 'Add'}
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      </div>

      <div className="d-flex justify-content-between align-items-center">
        <div className="d-flex align-items-center">
          <label className="me-2">Show</label>
          <select
            className="form-select w-auto"
            value={rowsPerPage}
            onChange={(e) => {
              setRowsPerPage(Number(e.target.value));
              setCurrentPage(1);
            }}
            disabled={isLoading}
          >
            <option value="10">10</option>
            <option value="20">20</option>
            <option value="50">50</option>
          </select>
          <span className="ms-2">Entries</span>
        </div>
        <div>
          Showing {events.length === 0 ? 0 : (currentPage - 1) * rowsPerPage + 1} to{' '}
          {(currentPage - 1) * rowsPerPage + events.length} of {totalItems} entries
        </div>
        <div className="d-flex align-items-center">
          <div className="me-3">
            Page {currentPage} of {totalPages}
          </div>
          <button
            className="btn btn-sm btn-outline-secondary me-2"
            disabled={currentPage === 1 || isLoading}
            onClick={() => setCurrentPage((prev) => prev - 1)}
          >
            <i className="bi bi-chevron-left"></i>
          </button>
          <button
            className="btn btn-sm btn-outline-secondary"
            disabled={currentPage === totalPages || isLoading}
            onClick={() => setCurrentPage((prev) => prev + 1)}
          >
            <i className="bi bi-chevron-right"></i>
          </button>
        </div>
      </div>
    </div>
  );
}

export default EventSchedule;